// Get all unique college names for the top-level dropdown (sorted)
export const COLLEGE_NAMES: string[] = MAHARASHTRA_COLLEGES.map(c => c.college).sort();

// Get branches for a selected college
export function getBranchesForCollege(collegeName: string): string[] {
  const entry = MAHARASHTRA_COLLEGES.find(c => c.college === collegeName);
  return entry ? [...entry.branches].sort() : [];
}
